import { useIconColor } from '@advui/icons'
import { type ReactNode, useId, useRef, useState } from 'react'
import { type GetProps, View, VisuallyHidden, XStack, isWeb } from 'tamagui'
import { Button } from '../components/button/Button'
import { Text } from '../components/typography/Text'
import { Table } from '../components/table/Table'

/** One series (a line, a set of bars): the data field it reads and its name. */
export interface ChartSeries {
  key: string
  label: string
}

export interface ChartLabels {
  showTable: string
  hideTable: string
  /** Read before the arrow-key hint on the focused plot. */
  keyboardHint: string
}

export const defaultChartLabels: ChartLabels = {
  showTable: 'Show table',
  hideTable: 'Hide table',
  keyboardHint: 'Use the arrow keys to read each value.',
}

/** The chart palette, in its fixed order, as resolved colors. */
export function useChartColors(): string[] {
  // Hooks in a fixed order: one per slot.
  return [
    useIconColor('$chart1'),
    useIconColor('$chart2'),
    useIconColor('$chart3'),
    useIconColor('$chart4'),
    useIconColor('$chart5'),
    useIconColor('$chart6'),
    useIconColor('$chart7'),
    useIconColor('$chart8'),
  ].map((color) => color ?? 'currentColor')
}

/** Axis text, gridlines and the surface, as resolved colors. */
export function useChartInk(surface: string) {
  return {
    text: useIconColor('$mutedForeground') ?? 'currentColor',
    grid: useIconColor('$border') ?? 'currentColor',
    axis: useIconColor('$borderStrong') ?? 'currentColor',
    surface: useIconColor(surface) ?? 'transparent',
  }
}

export interface LegendItem {
  label: string
  color: string
  /** Mirrors the mark: a line for line charts, a square for bars, areas and slices. */
  shape: 'line' | 'square'
  /** Extra text after the label, e.g. a slice's share. */
  detail?: string
}

export interface TooltipContent {
  title: string
  rows: { label: string; value: string; color: string; shape: LegendItem['shape'] }[]
}

export interface ChartFrameProps {
  /** Names the chart (its accessible name and heading). */
  title: string
  description?: string
  legend: LegendItem[]
  /** Plot height in pixels, including the axes. */
  height: number
  /** Fixed plot width; by default the chart fills its container. */
  width?: number
  /** Number of positions the arrow keys step through. */
  count: number
  /** The position under a point in the plot, or null. */
  hitTest: (x: number, y: number, width: number) => number | null
  tooltip: (index: number) => TooltipContent | null
  /** Where the tooltip points, in plot coordinates. */
  anchor: (index: number, width: number) => { x: number; y: number }
  /** Draws the plot at the measured width; `active` is the hovered position. */
  children: (width: number, active: number | null) => ReactNode
  table: { columns: string[]; rows: string[][]; numeric: boolean[] }
  labels?: Partial<ChartLabels>
  frameProps?: GetProps<typeof View>
}

/**
 * The frame every chart shares: title, legend, a measured plot with a
 * tooltip (hover, tap or arrow keys), and a table view of the same data.
 */
export function ChartFrame({
  title,
  description,
  legend,
  height,
  width: fixedWidth,
  count,
  hitTest,
  tooltip,
  anchor,
  children,
  table,
  labels: labelsProp,
  frameProps,
}: ChartFrameProps) {
  const labels = { ...defaultChartLabels, ...labelsProp }
  const [measured, setMeasured] = useState(0)
  const width = fixedWidth ?? measured
  const [active, setActive] = useState<number | null>(null)
  const [showTable, setShowTable] = useState(false)
  const titleId = useId()
  const tableId = useId()
  const plotRef = useRef<HTMLElement | null>(null)
  const content = active != null ? tooltip(active) : null

  const pointAt = (clientX: number, clientY: number) => {
    const rect = plotRef.current?.getBoundingClientRect()
    if (!rect) return
    setActive(hitTest(clientX - rect.left, clientY - rect.top, width))
  }

  const onKeyDown = (event: { key: string; preventDefault: () => void }) => {
    const last = count - 1
    const moves: Record<string, number> = {
      ArrowRight: Math.min(last, (active ?? -1) + 1),
      ArrowDown: Math.min(last, (active ?? -1) + 1),
      ArrowLeft: Math.max(0, (active ?? count) - 1),
      ArrowUp: Math.max(0, (active ?? count) - 1),
      Home: 0,
      End: last,
    }
    if (event.key in moves && count > 0) {
      event.preventDefault()
      setActive(moves[event.key]!)
    } else if (event.key === 'Escape') setActive(null)
  }

  const point = active != null && width > 0 ? anchor(active, width) : null
  const summary = content
    ? `${content.title}: ${content.rows.map((r) => `${r.label} ${r.value}`).join(', ')}`
    : ''

  return (
    <View
      render="figure"
      margin={0}
      gap="$3"
      width="100%"
      aria-labelledby={titleId}
      {...frameProps}
    >
      <View gap="$1">
        <Text id={titleId} size="sm" weight="semibold">
          {title}
        </Text>
        {description ? (
          <Text size="xs" tone="muted">
            {description}
          </Text>
        ) : null}
      </View>

      {legend.length > 0 ? (
        <XStack flexWrap="wrap" columnGap="$4" rowGap="$1.5">
          {legend.map((item) => (
            <XStack key={item.label} alignItems="center" gap="$1.5">
              <View
                aria-hidden
                backgroundColor={item.color as never}
                width={item.shape === 'line' ? '$3' : '$2.5'}
                height={item.shape === 'line' ? 2 : '$2.5'}
                borderRadius={item.shape === 'line' ? '$full' : '$xs'}
              />
              <Text size="xs" tone="muted">
                {item.label}
                {item.detail ? ` · ${item.detail}` : ''}
              </Text>
            </XStack>
          ))}
        </XStack>
      ) : null}

      <View
        ref={plotRef as never}
        position="relative"
        height={height}
        width={fixedWidth ?? '100%'}
        onLayout={(event: { nativeEvent: { layout: { width: number } } }) =>
          setMeasured(Math.floor(event.nativeEvent.layout.width))
        }
        // The plot is one focusable image; the arrow keys read it point by point.
        role="img"
        aria-label={`${title}. ${description ? `${description}. ` : ''}${labels.keyboardHint}`}
        {...(isWeb
          ? {
              tabIndex: 0,
              onKeyDown,
              onBlur: () => setActive(null),
              onMouseMove: (event: { clientX: number; clientY: number }) =>
                pointAt(event.clientX, event.clientY),
              onMouseLeave: () => setActive(null),
            }
          : {
              accessible: true,
              // Native has no live region here: the reading becomes the plot's value.
              ...(summary && { accessibilityValue: { text: summary } }),
              onPress: (event: { nativeEvent: { locationX: number; locationY: number } }) =>
                setActive(hitTest(event.nativeEvent.locationX, event.nativeEvent.locationY, width)),
            })}
        borderRadius="$sm"
        focusVisibleStyle={{
          outlineColor: '$ring',
          outlineStyle: 'solid',
          outlineWidth: 2,
          outlineOffset: 4,
        }}
      >
        {width > 0 ? children(width, active) : null}
        {content && point ? (
          <View
            aria-hidden
            pointerEvents="none"
            position="absolute"
            top={0}
            {...(point.x < width / 2 ? { left: point.x + 12 } : { right: width - point.x + 12 })}
            backgroundColor="$popover"
            borderWidth={1}
            borderColor="$border"
            borderRadius="$md"
            paddingHorizontal="$2.5"
            paddingVertical="$2"
            gap="$1"
            minWidth="$32"
            zIndex={1}
          >
            <Text size="xs" tone="muted">
              {content.title}
            </Text>
            {content.rows.map((row) => (
              <XStack key={row.label} alignItems="center" gap="$2">
                <View
                  backgroundColor={row.color as never}
                  width="$2.5"
                  height={row.shape === 'line' ? 2 : '$2.5'}
                  borderRadius={row.shape === 'line' ? '$full' : '$xs'}
                />
                <Text size="sm" weight="semibold">
                  {row.value}
                </Text>
                <Text size="xs" tone="muted" flexShrink={1}>
                  {row.label}
                </Text>
              </XStack>
            ))}
          </View>
        ) : null}
      </View>
      {/* Outside the plot: an img's contents are hidden from assistive technology. */}
      {isWeb ? <VisuallyHidden aria-live="polite">{summary}</VisuallyHidden> : null}

      <View alignItems="flex-start" gap="$2">
        <Button
          size="sm"
          variant="ghost"
          // Lines the label up with the title above.
          marginLeft="$-3"
          aria-expanded={showTable}
          {...(isWeb && { 'aria-controls': tableId })}
          onPress={() => setShowTable(!showTable)}
        >
          {showTable ? labels.hideTable : labels.showTable}
        </Button>
        {showTable ? (
          <View id={tableId} width="100%">
            <Table aria-label={title} size="sm" minWidth={Math.max(320, table.columns.length * 96)}>
              <Table.Header>
                <Table.Row>
                  {table.columns.map((column, i) => (
                    <Table.Head key={column} align={table.numeric[i] ? 'end' : 'start'}>
                      {column}
                    </Table.Head>
                  ))}
                </Table.Row>
              </Table.Header>
              <Table.Body>
                {table.rows.map((row, r) => (
                  <Table.Row key={r}>
                    {row.map((cell, i) => (
                      <Table.Cell key={i} align={table.numeric[i] ? 'end' : 'start'}>
                        {cell}
                      </Table.Cell>
                    ))}
                  </Table.Row>
                ))}
              </Table.Body>
            </Table>
          </View>
        ) : null}
      </View>
    </View>
  )
}

import { CategoryLabels, ValueGrid, cartesianPadding } from './cartesian'
import {
  ChartFrame,
  type ChartLabels,
  type ChartSeries,
  useChartColors,
  useChartInk,
} from './ChartFrame'
import { formatFull, numberAt } from './format'
import { linearScale, niceTicks } from './scale'
import { Circle, G, Line, Path, Svg } from './svg'

export interface LinePlotProps {
  title: string
  description?: string
  /** One object per x position, e.g. `{ month: 'Jan', reached: 1200 }`. */
  data: Record<string, unknown>[]
  /** The field holding each row's x label. */
  index: string
  /** Heading of the x column in the table view. Default: `index`. */
  indexLabel?: string
  /** The numeric fields to plot, in color order. */
  series: ChartSeries[]
  /** Height in pixels, including the axes. Default: 240. */
  height?: number
  width?: number
  /** Formats values in the tooltip and table. Axis ticks are compact (1.2K). */
  valueFormatter?: (value: number) => string
  /** Plot area always starts at zero. Default: true for areas, false for lines. */
  startAtZero?: boolean
  /**
   * Color of the surface the chart sits on, for the ring around markers.
   * Default: `$background`; use `$card` inside a Card.
   */
  surface?: string
  labels?: Partial<ChartLabels>
}

/** Shared by LineChart and AreaChart. */
export function LinePlot({
  title,
  description,
  data,
  index,
  indexLabel = index,
  series,
  height = 240,
  width,
  valueFormatter = formatFull,
  startAtZero,
  surface = '$background',
  labels,
  area = false,
  stacked = false,
}: LinePlotProps & { area?: boolean; stacked?: boolean }) {
  const colors = useChartColors()
  const ink = useChartInk(surface)
  const categories = data.map((row) => String(row[index] ?? ''))
  const values = data.map((row) => series.map((s) => numberAt(row, s.key)))

  // Stacked areas draw each series on top of the ones before it.
  const tops = values.map((row) => {
    let sum = 0
    return row.map((v) => (v == null ? null : stacked ? (sum += v) : v))
  })
  const all = tops.flat().filter((v): v is number => v != null)
  const zero = startAtZero ?? area
  const ticks = niceTicks(
    zero ? Math.min(0, ...all) : Math.min(...all),
    zero ? Math.max(0, ...all) : Math.max(...all),
  )
  const pad = cartesianPadding(ticks)
  const n = data.length

  const scales = (w: number) => {
    const step = (w - pad.left - pad.right) / Math.max(1, n)
    return {
      step,
      x: (i: number) => pad.left + (i + 0.5) * step,
      y: linearScale([ticks[0]!, ticks.at(-1)!], [height - pad.bottom, pad.top]),
    }
  }

  const format = (value: number | null) => (value == null ? '–' : valueFormatter(value))
  const shape = area ? ('square' as const) : ('line' as const)

  return (
    <ChartFrame
      title={title}
      description={description}
      legend={
        series.length > 1
          ? series.map((s, i) => ({ label: s.label, color: colors[i % 8]!, shape }))
          : []
      }
      height={height}
      width={width}
      count={n}
      hitTest={(x, _y, w) => {
        const { step } = scales(w)
        const i = Math.round((x - pad.left) / step - 0.5)
        return Math.max(0, Math.min(n - 1, i))
      }}
      anchor={(i, w) => ({ x: scales(w).x(i), y: pad.top })}
      tooltip={(i) => ({
        title: categories[i]!,
        rows: series.map((s, j) => ({
          label: s.label,
          value: format(values[i]![j]!),
          color: colors[j % 8]!,
          shape,
        })),
      })}
      table={{
        columns: [indexLabel, ...series.map((s) => s.label)],
        rows: data.map((_, i) => [categories[i]!, ...values[i]!.map(format)]),
        numeric: [false, ...series.map(() => true)],
      }}
      labels={labels}
    >
      {(w, active) => {
        const { x, y, step } = scales(w)
        const base = (i: number, j: number) =>
          stacked && j > 0 ? (tops[i]![j - 1] ?? 0) : Math.max(ticks[0]!, 0)
        return (
          <Svg width={w} height={height}>
            <ValueGrid ticks={ticks} y={y} left={pad.left} right={w - pad.right} ink={ink} />
            <CategoryLabels
              labels={categories}
              x={x}
              y={height - pad.bottom + 4}
              available={step}
              ink={ink}
            />
            {active != null ? (
              <Line
                x1={x(active)}
                x2={x(active)}
                y1={pad.top}
                y2={height - pad.bottom}
                stroke={ink.axis}
                strokeWidth={1}
              />
            ) : null}
            {series.map((s, j) => {
              const color = colors[j % 8]!
              // A missing value breaks the line instead of dropping to zero.
              const runs: number[][] = [[]]
              tops.forEach((row, i) => {
                if (row[j] == null) runs.push([])
                else runs.at(-1)!.push(i)
              })
              return (
                <G key={s.key}>
                  {runs
                    .filter((run) => run.length > 0)
                    .map((run) => {
                      const line = run
                        .map((i, k) => `${k === 0 ? 'M' : 'L'}${x(i)},${y(tops[i]![j]!)}`)
                        .join('')
                      const fill = area
                        ? `${line}${[...run]
                            .reverse()
                            .map((i) => `L${x(i)},${y(base(i, j))}`)
                            .join('')}Z`
                        : null
                      // A lone value between gaps has no line to draw: show it as a dot.
                      if (run.length === 1) {
                        const i = run[0]!
                        return <Circle key={i} cx={x(i)} cy={y(tops[i]![j]!)} r={3} fill={color} />
                      }
                      return (
                        <G key={run[0]}>
                          {fill ? <Path d={fill} fill={color} fillOpacity={0.1} /> : null}
                          <Path
                            d={line}
                            fill="none"
                            stroke={color}
                            strokeWidth={2}
                            strokeLinejoin="round"
                            strokeLinecap="round"
                          />
                        </G>
                      )
                    })}
                </G>
              )
            })}
            {/* End markers, and every series' marker at the hovered position, ringed in the surface color. */}
            {series.map((s, j) => {
              const color = colors[j % 8]!
              const lastIndex = tops.reduce<number>(
                (last, row, i) => (row[j] != null ? i : last),
                -1,
              )
              const points = new Set([lastIndex, ...(active != null ? [active] : [])])
              return [...points]
                .filter((i) => i >= 0 && tops[i]?.[j] != null)
                .map((i) => (
                  <Circle
                    key={`${s.key}-${i}`}
                    cx={x(i)}
                    cy={y(tops[i]![j]!)}
                    r={4}
                    fill={color}
                    stroke={ink.surface}
                    strokeWidth={2}
                  />
                ))
            })}
          </Svg>
        )
      }}
    </ChartFrame>
  )
}

import { Line, SvgText } from './svg'
import { formatCompact } from './format'

/** Space around the plot for axis labels. */
export function cartesianPadding(
  ticks: number[],
  format: (value: number) => string = formatCompact,
) {
  // About 7px per character of the widest tick label at 12px.
  const labelWidth = Math.max(...ticks.map((t) => format(t).length)) * 7
  return { top: 8, right: 8, bottom: 24, left: labelWidth + 12 }
}

/** Horizontal gridlines with value labels on the left. */
export function ValueGrid({
  ticks,
  y,
  left,
  right,
  ink,
  format = formatCompact,
}: {
  ticks: number[]
  y: (value: number) => number
  left: number
  right: number
  ink: { text: string; grid: string; axis: string }
  format?: (value: number) => string
}) {
  return (
    <>
      {ticks.map((tick) => (
        <Line
          key={`grid-${tick}`}
          x1={left}
          x2={right}
          y1={y(tick)}
          y2={y(tick)}
          stroke={tick === 0 ? ink.axis : ink.grid}
          strokeWidth={1}
        />
      ))}
      {ticks.map((tick) => (
        <SvgText
          key={`label-${tick}`}
          x={left - 8}
          y={y(tick)}
          dy="0.35em"
          fill={ink.text}
          fontSize={12}
          textAnchor="end"
        >
          {format(tick)}
        </SvgText>
      ))}
    </>
  )
}

/**
 * Category labels under the plot. When they would overlap, only every nth
 * is drawn (the first and the rest in steps), so none collide.
 */
export function CategoryLabels({
  labels,
  x,
  y,
  available,
  ink,
}: {
  labels: string[]
  x: (index: number) => number
  y: number
  /** Width each label may use before thinning kicks in. */
  available: number
  ink: { text: string }
}) {
  const widest = Math.max(1, ...labels.map((l) => l.length)) * 7 + 8
  const step = Math.max(1, Math.ceil(widest / Math.max(1, available)))
  return (
    <>
      {labels.map((label, index) =>
        index % step === 0 ? (
          <SvgText
            key={`${label}-${index}`}
            x={x(index)}
            y={y}
            dy="0.9em"
            fill={ink.text}
            fontSize={12}
            textAnchor="middle"
          >
            {label}
          </SvgText>
        ) : null,
      )}
    </>
  )
}

const compact = new Intl.NumberFormat('en-US', { notation: 'compact', maximumFractionDigits: 1 })
const full = new Intl.NumberFormat('en-US', { maximumFractionDigits: 2 })

/** Axis ticks: 1.2K, 3.4M. */
export const formatCompact = (value: number) => compact.format(value)

/** Tooltips and the table: 1,234.5. */
export const formatFull = (value: number) => full.format(value)

/** Reads a numeric field; anything else counts as missing. */
export function numberAt(row: Record<string, unknown>, key: string): number | null {
  const value = row[key]
  return typeof value === 'number' && Number.isFinite(value) ? value : null
}

/** Clean, round tick values ("nice numbers") covering [min, max]. */
export function niceTicks(min: number, max: number, count = 5): number[] {
  if (!Number.isFinite(min) || !Number.isFinite(max)) return [0]
  if (min === max) {
    if (min === 0) return [0, 1]
    ;[min, max] = min > 0 ? [0, min] : [min, 0]
  }
  const step = niceStep((max - min) / Math.max(1, count - 1))
  const start = Math.floor(min / step) * step
  const end = Math.ceil(max / step) * step
  const ticks: number[] = []
  // Rounding keeps 0.1 + 0.2 style float noise out of the labels.
  for (let v = start; v <= end + step / 2; v += step) ticks.push(Number(v.toPrecision(12)))
  return ticks
}

function niceStep(raw: number): number {
  const power = 10 ** Math.floor(Math.log10(raw))
  const fraction = raw / power
  const nice =
    fraction <= 1 ? 1 : fraction <= 2 ? 2 : fraction <= 2.5 ? 2.5 : fraction <= 5 ? 5 : 10
  return nice * power
}

/** Maps a value in [d0, d1] to [r0, r1]. */
export function linearScale([d0, d1]: [number, number], [r0, r1]: [number, number]) {
  const span = d1 - d0 || 1
  return (value: number) => r0 + ((value - d0) / span) * (r1 - r0)
}

/**
 * Splits [start, end] into `count` equal bands; `band(i)` is the start of
 * band i and `bandwidth` its size.
 */
export function bandScale(count: number, [start, end]: [number, number]) {
  const bandwidth = (end - start) / Math.max(1, count)
  return { band: (index: number) => start + index * bandwidth, bandwidth }
}

/**
 * A rectangle with rounded corners on its data end only (the end away from
 * the baseline), as an SVG path. `direction` is where the data end points.
 */
export function barPath(
  x: number,
  y: number,
  width: number,
  height: number,
  radius: number,
  direction: 'up' | 'down' | 'right' | 'left',
): string {
  if (width <= 0 || height <= 0) return ''
  const r = Math.max(0, Math.min(radius, width / 2, height / 2))
  const x2 = x + width
  const y2 = y + height
  switch (direction) {
    case 'up':
      return `M${x},${y2}V${y + r}Q${x},${y} ${x + r},${y}H${x2 - r}Q${x2},${y} ${x2},${y + r}V${y2}Z`
    case 'down':
      return `M${x},${y}V${y2 - r}Q${x},${y2} ${x + r},${y2}H${x2 - r}Q${x2},${y2} ${x2},${y2 - r}V${y}Z`
    case 'right':
      return `M${x},${y}H${x2 - r}Q${x2},${y} ${x2},${y + r}V${y2 - r}Q${x2},${y2} ${x2 - r},${y2}H${x}Z`
    case 'left':
      return `M${x2},${y}H${x + r}Q${x},${y} ${x},${y + r}V${y2 - r}Q${x},${y2} ${x + r},${y2}H${x2}Z`
  }
}

/** A pie or donut slice as an SVG path; angles in radians, 0 at 12 o'clock. */
export function arcPath(
  cx: number,
  cy: number,
  outer: number,
  inner: number,
  start: number,
  end: number,
): string {
  const point = (radius: number, angle: number) =>
    `${cx + radius * Math.sin(angle)},${cy - radius * Math.cos(angle)}`
  const large = end - start > Math.PI ? 1 : 0
  // A full circle cannot be one arc: split it in two.
  if (end - start >= Math.PI * 2 - 1e-6) {
    const mid = start + Math.PI
    return inner > 0
      ? `M${point(outer, start)}A${outer},${outer} 0 1 1 ${point(outer, mid)}A${outer},${outer} 0 1 1 ${point(outer, start)}` +
          `M${point(inner, start)}A${inner},${inner} 0 1 0 ${point(inner, mid)}A${inner},${inner} 0 1 0 ${point(inner, start)}Z`
      : `M${point(outer, start)}A${outer},${outer} 0 1 1 ${point(outer, mid)}A${outer},${outer} 0 1 1 ${point(outer, start)}Z`
  }
  return inner > 0
    ? `M${point(outer, start)}A${outer},${outer} 0 ${large} 1 ${point(outer, end)}L${point(inner, end)}A${inner},${inner} 0 ${large} 0 ${point(inner, start)}Z`
    : `M${cx},${cy}L${point(outer, start)}A${outer},${outer} 0 ${large} 1 ${point(outer, end)}Z`
}

